import numpy as np
A1=np.array([[1,0,0],[1,0,1],[0,0,1]])
B1=np.array([[0,1,0],[1,0,0],[0,1,0]])
A2=np.array([[0,1,0],[1,0,0],[0,1,1]])
B2=np.array([[0,1,0],[1,0,1],[0,1,0]])
T=np.array([[1,0,0],[1,0,1],[1,0,0]])
ops={'and':lambda a,b:a&b,'or':lambda a,b:a|b,'xor':lambda a,b:a^b,'a&~b':lambda a,b:a&~b,'~a&b':lambda a,b:~a&b,'nor':lambda a,b:~(a|b),'xnor':lambda a,b:~(a^b)}
def transforms(a):
 return {'id':a,'rot90':np.rot90(a,-1),'rot180':np.rot90(a,2),'rot270':np.rot90(a),'flipx':np.fliplr(a),'flipy':np.flipud(a),'transpose':a.T,'anti':np.rot90(a.T,2)}
for n,f in ops.items():
 for an,aa in transforms(A1).items():
  for bn,bb in transforms(B1).items():
   if np.array_equal(f(aa,bb)&1,T):
    aa2=transforms(A2)[an];bb2=transforms(B2)[bn]
    if np.array_equal(f(aa2,bb2)&1,T):print(n,an,bn)
